namespace App\Models;

use Illuminate\Database\Eloquent\Model;

/**
 * One row per approval transition: who moved which record from which
 * status to which status, with the optional comment.
 */
class ApprovalHistory extends Model
{
    protected $table = 'approval_histories';

    protected $fillable = [
        'record_type',
        'record_id',
        'from_status',
        'to_status',
        'comment',
        'user_id',
    ];

    /**
     * Parent record this approval entry belongs to.
     * @return  \Illuminate\Database\Eloquent\Relations\MorphTo  Morph-to relation.
     */
    public function record()
    {
        return $this->morphTo('record');
    }

    /**
     * User who performed the approval transition.
     * @return  \Illuminate\Database\Eloquent\Relations\BelongsTo  Belongs-to relation.
     */
    public function user()
    {
        return $this->belongsTo(User::class, 'user_id');
    }
}
